import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CZqXuAiL.js";const h=JSON.parse(`{"title":"What's New — v2.0 to v2.3.3","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/features/whats-new.md","filePath":"openshield-xdp/features/whats-new.md","lastUpdated":null}`),s={name:"openshield-xdp/features/whats-new.md"};function n(i,e,l,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="what-s-new-—-v2-0-to-v2-3-3" tabindex="-1">What&#39;s New — v2.0 to v2.3.3 <a class="header-anchor" href="#what-s-new-—-v2-0-to-v2-3-3" aria-label="Permalink to &quot;What&#39;s New — v2.0 to v2.3.3&quot;">​</a></h1><p>The feature changelog for the 2.x line. For the complete feature map see <a href="/pingless-studios-docs/openshield-xdp/features/">Everything OpenShield-XDP Does</a>.</p><h2 id="v2-3-3-—-boot-autostart-crash-immunity" tabindex="-1">v2.3.3 — Boot autostart &amp; crash-immunity <a class="header-anchor" href="#v2-3-3-—-boot-autostart-crash-immunity" aria-label="Permalink to &quot;v2.3.3 — Boot autostart &amp; crash-immunity&quot;">​</a></h2><ul><li><strong><code>openshield load -always</code></strong> — one flag enables auto-load on every boot via the systemd unit. Self-heals a missing unit file from the pristine copy in <code>/opt/openshield/lib</code>, and verifies the enable actually took.</li><li><strong>Admin IP protection, guaranteed</strong> — the loader binary (what systemd runs at boot) now also auto-whitelists your SSH source IP; the persisted entry is re-applied on every boot before the first packet is judged.</li><li><strong>Hardened systemd unit</strong> — waits for <code>network-online.target</code> (no more racing the interface at boot), and <code>StartLimitIntervalSec=0</code> means a crash loop never puts the firewall into a permanent failed state.</li><li><strong>Silent-crash immunity baked into every binary</strong> — on some kernels/hypervisors the Go runtime&#39;s async preemption killed the loader instantly with no output. All binaries now self-apply the documented workaround (<code>GODEBUG=asyncpreemptoff=1</code>) via a transparent re-exec, so manual runs are as safe as the systemd unit.</li></ul><h2 id="v2-3-2-—-cli-help-system-tui-bugfix-sweep" tabindex="-1">v2.3.2 — CLI help system &amp; TUI bugfix sweep <a class="header-anchor" href="#v2-3-2-—-cli-help-system-tui-bugfix-sweep" aria-label="Permalink to &quot;v2.3.2 — CLI help system &amp; TUI bugfix sweep&quot;">​</a></h2><ul><li><strong>Per-command help pages</strong> — <code>openshield help &lt;command&gt;</code> / <code>--help</code> anywhere, driven by one registry so overall and per-command help can never drift.</li><li><strong>18 TUI fixes</strong> — geo-tab crash on empty search, never-block input digit handling, traffic screen wraps below 140 columns, typed <code>config_update</code> replies (live config edits no longer look lost), confirm dialogs honor Ctrl+C, uptime-based health badges, narrow-terminal layout, scrollable help overlay, complete keybind docs, input validation, and more.</li></ul><h2 id="v2-3-1-—-self-traffic-exclusion-startup-warmup" tabindex="-1">v2.3.1 — Self-traffic exclusion &amp; startup warmup <a class="header-anchor" href="#v2-3-1-—-self-traffic-exclusion-startup-warmup" aria-label="Permalink to &quot;v2.3.1 — Self-traffic exclusion &amp; startup warmup&quot;">​</a></h2><ul><li><strong>Your own downloads no longer fake attacks</strong> — replies to the server&#39;s outbound connections (GeoIP updates, blocklist fetches, apt) are excluded from attack-detection and baseline-learning rates. Root-caused: the global counters ran before every exemption. <a href="/pingless-studios-docs/openshield-xdp/features/silent-guardians#your-own-downloads-never-fake-an-attack">How it works</a></li><li><strong><code>attack_warmup_sec</code></strong> (default 20) — no attack declaration in the first seconds after loader start; per-IP mitigation unaffected.</li></ul><h2 id="v2-3-0-—-smarter-feeds-bigger-maps" tabindex="-1">v2.3.0 — Smarter feeds, bigger maps <a class="header-anchor" href="#v2-3-0-—-smarter-feeds-bigger-maps" aria-label="Permalink to &quot;v2.3.0 — Smarter feeds, bigger maps&quot;">​</a></h2><ul><li><strong>Auto-fetch <code>vps</code> / <code>dedicated</code> modes</strong> — dedicated mode skips known cloud/hosting provider ranges (Cloudflare, AWS, GCP live lists + offline fallback) so customer nodes on a dedicated box are never feed-banned.</li><li><strong>List hygiene</strong> — whitelabel (never-block) syncing with the whitelist, blacklist↔whitelist conflict resolution.</li><li><strong>2M-entry ban maps</strong> (IPv4) — million-IP botnets fit with headroom (~1 GB).</li></ul><h2 id="v2-2-x-—-geo-blocking-alert-quality" tabindex="-1">v2.2.x — Geo blocking &amp; alert quality <a class="header-anchor" href="#v2-2-x-—-geo-blocking-alert-quality" aria-label="Permalink to &quot;v2.2.x — Geo blocking &amp; alert quality&quot;">​</a></h2><ul><li><strong>Geo country blocking</strong> — one keypress blocks a country; ranges resolve from MaxMind GeoLite2 into permanent subnet bans, with persisted records and one-keypress unblock. Geo analytics (top attacking countries with flags, IPs, PPS, Gbps, share %) in attack-end reports and daily/weekly/monthly reports.</li><li><strong>Ban notes</strong> — optional notes on every ban; geo blocks use them for surgical unblocking.</li><li><strong>Alert cadence rework</strong> — growing-interval progress updates, guaranteed end-of-attack delivery with the full report, oversized-forensics fallback message.</li><li><strong>Port-cap player protection</strong> — established and pre-attack sources exempt from the per-port attack cap.</li></ul><h2 id="v2-1-x-—-metrics-obfuscation-rotation-proof-caps" tabindex="-1">v2.1.x — Metrics, obfuscation, rotation-proof caps <a class="header-anchor" href="#v2-1-x-—-metrics-obfuscation-rotation-proof-caps" aria-label="Permalink to &quot;v2.1.x — Metrics, obfuscation, rotation-proof caps&quot;">​</a></h2><ul><li><strong>Metrics HTTP API</strong> — optional endpoint with everything the TUI shows; API key (yours or auto-generated), rate limits, allowlist.</li><li><strong>Obfuscated prebuilt releases</strong> — garble-built binaries, zero source in the production zip; dual packaging (bin + src).</li><li><strong>Attack per-port aggregate cap</strong> — the rotation-proof answer to spoofed floods.</li><li><strong>New-source temp bans</strong> — replaces drop-only handling of source bursts.</li><li><strong>Forensics config evidence</strong> — every attack bundle includes the config (with change timestamps) active during it.</li><li><strong>Runtime config edits persist</strong> — TUI/live edits write through to the YAML.</li></ul><h2 id="v2-0-0-—-the-sftp-fix" tabindex="-1">v2.0.0 — The SFTP fix <a class="header-anchor" href="#v2-0-0-—-the-sftp-fix" aria-label="Permalink to &quot;v2.0.0 — The SFTP fix&quot;">​</a></h2><ul><li><strong>Established-connection exemption (A2)</strong> — proven TCP connections (handshake + real data) are exempt from rate scoring. Bulk transfers — SFTP uploads, backups, replication — never get banned again. <a href="/pingless-studios-docs/openshield-xdp/features/silent-guardians#your-sftp-uploads-never-get-you-banned">The full story</a></li><li><strong>Per-port threshold overrides (C)</strong> — custom PPS/BPS limits for specific ports or port ranges, replacing both normal and attack-mode thresholds on those ports only.</li></ul>',16)])])}const g=t(s,[["render",n]]);export{h as __pageData,g as default};
